// TypeScript Version: 4.1

/**
* Interface describing `dlartg`.
*/
interface Routine {
	/**
	* Constructs a Givens rotation of a two-dimensional vector that zeros out the second component.
	*
	* For a two-dimensional vector ( f, g ) it computes the sine `S`, cosine `C` and the resultant `R` such that the following equation is satisfied:
	*
	* ```tex
	* \(\begin{bmatrix} C & S \\ -S & C \end{bmatrix} \begin{bmatrix} F \\ G \end{bmatrix} = \begin{bmatrix} R \\ 0 \end{bmatrix}\)
	* ```
	*
	* @param F - single element array containing the first component of the vector to be rotated
	* @param G - single element array containing the second component of the vector to be rotated
	* @param C - single element array which is overwritten by the cosine of the rotation
	* @param S - single element array which is overwritten by the sine of the rotation
	* @param R - single element array which is overwritten by the length of the rotated vector
	* @returns {void}
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var F = new Float64Array( [ 3.0 ] );
	* var G = new Float64Array( [ 4.0 ] );
	* var C = new Float64Array( 1 );
	* var S = new Float64Array( 1 );
	* var R = new Float64Array( 1 );
	*
	* dlartg( F, G, C, S, R );
	* // R => <Float64Array>[ 5.0 ]
	* // C => <Float64Array>[ 0.6 ]
	* // S => <Float64Array>[ 0.8 ]
	*/
	( F: Float64Array, G: Float64Array, C: Float64Array, S: Float64Array, R: Float64Array ): void;

	/**
	* Constructs a Givens rotation of a two-dimensional vector that zeros out the second component.
	*
	* For a two-dimensional vector ( f, g ) it computes the sine `S`, cosine `C` and the resultant `R` such that the following equation is satisfied:
	*
	* ```tex
	* \(\begin{bmatrix} C & S \\ -S & C \end{bmatrix} \begin{bmatrix} F \\ G \end{bmatrix} = \begin{bmatrix} R \\ 0 \end{bmatrix}\)
	* ```
	*
	* @param F - single element array containing the first component of the vector to be rotated
	* @param offsetF - index of the element in `F`
	* @param G - single element array containing the second component of the vector to be rotated
	* @param offsetG - index of the element in `G`
	* @param C - single element array which is overwritten by the cosine of the rotation
	* @param offsetC - index of the element in `C`
	* @param S - single element array which is overwritten by the sine of the rotation
	* @param offsetS - index of the element in `S`
	* @param R - single element array which is overwritten by the length of the rotated vector
	* @param offsetR - index of the element in `R`
	* @returns {void}
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var F = new Float64Array( [ 3.0 ] );
	* var G = new Float64Array( [ 4.0 ] );
	* var C = new Float64Array( 1 );
	* var S = new Float64Array( 1 );
	* var R = new Float64Array( 1 );
	*
	* dlartg.ndarray( F, 0, G, 0, C, 0, S, 0, R, 0 );
	* // R => <Float64Array>[ 5.0 ]
	* // C => <Float64Array>[ 0.6 ]
	* // S => <Float64Array>[ 0.8 ]
	*/
	ndarray( F: Float64Array, offsetF: number, G: Float64Array, offsetG: number, C: Float64Array, offsetC: number, S: Float64Array, offsetS: number, R: Float64Array, offsetR: number ): void;
}

/**
* Constructs a Givens rotation of a two-dimensional vector that zeros out the second component.
*
* For a two-dimensional vector ( f, g ) it computes the sine `S`, cosine `C` and the resultant `R` such that the following equation is satisfied:
*
* ```tex
* \(\begin{bmatrix} C & S \\ -S & C \end{bmatrix} \begin{bmatrix} F \\ G \end{bmatrix} = \begin{bmatrix} R \\ 0 \end{bmatrix}\)
* ```
*
* @param F - single element array containing the first component of the vector to be rotated
* @param G - single element array containing the second component of the vector to be rotated
* @param C - single element array which is overwritten by the cosine of the rotation
* @param S - single element array which is overwritten by the sine of the rotation
* @param R - single element array which is overwritten by the length of the rotated vector
* @returns {void}
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var F = new Float64Array( [ 3.0 ] );
* var G = new Float64Array( [ 4.0 ] );
* var C = new Float64Array( 1 );
* var S = new Float64Array( 1 );
* var R = new Float64Array( 1 );
*
* dlartg( F, G, C, S, R );
* // R => <Float64Array>[ 5.0 ]
* // C => <Float64Array>[ 0.6 ]
* // S => <Float64Array>[ 0.8 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var F = new Float64Array( [ 3.0 ] );
* var G = new Float64Array( [ 4.0 ] );
* var C = new Float64Array( 1 );
* var S = new Float64Array( 1 );
* var R = new Float64Array( 1 );
*
* dlartg.ndarray( F, 0, G, 0, C, 0, S, 0, R, 0 );
* // R => <Float64Array>[ 5.0 ]
* // C => <Float64Array>[ 0.6 ]
* // S => <Float64Array>[ 0.8 ]
*/
declare var dlartg: Routine;


// EXPORTS //

export = dlartg;
